import React from "react";
import { Routes, Route } from "react-router-dom";

import Home from "./pages/Home";
import Separate from "./components/Separate";
import SearchPage from "./pages/SearchPage";
import AboutPage from "./pages/AboutPage";
import Login from "./components/Login";
import IndividualPage from "./pages/IndividualPage";
import EditionPage from "./pages/EditionPage";
import MySpaceIndividual from "./pages/MySpaceIndividual";
import MySpace from "./pages/MySpacePage";
import MySpaceSubmitForm from "./components/MySpaceSubmitForm";

import Dashboard from "./backend/Dashboard";
import MySpacePanel from "./backend/MySpacePanel";
import ArticlesPanel from "./backend/ArticlesPanel";
import EditionsAdmin from "./backend/EditionsAdmin";
import AdminRequests from "./backend/AdminRequests";

import ProtectedRoute from "./components/ProtectedRoute";

export default function AppRoutes() {
  return (
    <Routes>
      {/* 🌍 PUBLIC ROUTES */}
      <Route path="/" element={<Home />} />
      <Route path="/search" element={<SearchPage />} />
      <Route path="/about" element={<AboutPage />} />
      <Route path="/login" element={<Login />} />

      <Route path="/individual/:id" element={<IndividualPage />} />
      <Route path="/category/:type" element={<Separate />} />
      <Route path="/separate" element={<Separate />} />

      <Route path="/myspace" element={<MySpace />} />
      <Route path="/myspace/:id" element={<MySpaceIndividual />} />
      <Route path="/myspaceclient" element={<MySpaceSubmitForm />} />

      <Route path="/editions" element={<EditionPage />} />
      <Route path="/editionsadmin" element={<EditionsAdmin/>}  />

      {/* 🔒 PROTECTED ADMIN ROUTES */}
      <Route
        path="/dashboard"
        element={
          <ProtectedRoute>
            <Dashboard />
          </ProtectedRoute>
        }
      />

      <Route
        path="/articlespanel"
        element={
          <ProtectedRoute>
            <ArticlesPanel />
          </ProtectedRoute>
        }
      />

      <Route
        path="/articlespanel"
        element={
          <ProtectedRoute>
            <ArticlesPanel />
          </ProtectedRoute>
        }
      />

      <Route
        path="/editionedit"
        element={
          <ProtectedRoute>
            <EditionsAdmin />
          </ProtectedRoute>
        }
      />

      <Route
        path="/adminrequest"
        element={
          <ProtectedRoute>
            <AdminRequests />
          </ProtectedRoute>
        }
      />

      <Route
        path="/myspacepanel"
        element={
          <ProtectedRoute>
            <MySpacePanel />
          </ProtectedRoute>
        }
      />
    </Routes>
  );
}
